from PIL import Image
import numpy as np, cv2
im=np.array(Image.open('first_frame.png'))
hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
regions={'arc':(85,135,8,30,(30,75)),'purple':(95,130,40,70,(120,160)),'bluelow':(125,172,65,88,(90,125)),'green':(60,145,78,105,(30,75)),'yellow':(85,165,115,140,(18,38)),'bluetop':(145,207,42,83,(90,125))}
for name,(x0,x1,y0,y1,(hl,hh)) in regions.items():
 print('\\n',name)
 m=(hsv[:,:,0]>=hl)&(hsv[:,:,0]<hh)&(hsv[:,:,1]>60)&(hsv[:,:,2]>40)
 for x in range(x0,x1,3):
  ys=np.where(m[y0:y1,x])[0]+y0
  if len(ys): print(x, int(np.median(ys)), int(ys.min()),int(ys.max()),len(ys))
